}

struct Snapshot {
    Tracker best;
};

Tracker named() {
    Tracker t;
    return t;  // NRVO
}

Tracker forced() {
    Tracker t;
    return std::move(t);  // blocks NRVO
}

Tracker either(bool first) {
    Tracker a, b;
    if (first) {
        return a;  // two candidates: implicit move
    }
    return b;
}

Tracker best_of() {
    Snapshot s;
    return std::move(s.best);  // a member: std::move belongs here
}

Tracker pick(bool first) {
    Tracker a, b;
    return first ? a : b;  // not a plain name: copy
}

int main() {
    label("named()");
    Tracker r1 = named();
    label("forced()");
    Tracker r2 = forced();
    label("either(true)");
    Tracker r3 = either(true);
    label("best_of()");
    Tracker r4 = best_of();
    label("pick(true)");
    Tracker r5 = pick(true);
    std::cout << "copies " << Tracker::copies << ", moves " << Tracker::moves << '\n';
    return 0;
}

