        std::cout << "copy\n";
        return *this;
    }
    Tracker& operator=(Tracker&&) noexcept {
        ++moves;
        std::cout << "move\n";
        return *this;
    }
};

struct Quote {  // rule of zero
    std::string venue;
    Tracker trace;
};

struct LoggedQuote {  // a destructor of its own
    std::string venue;
    Tracker trace;
    ~LoggedQuote() {}
};

template <typename T>
void fill(const char* name, int n, bool reserve_first) {
    std::cout << "-- " << name << '\n';
    Tracker::copies = 0;
    Tracker::moves = 0;
    std::vector<T> quotes;
    if (reserve_first) {
        quotes.reserve(n);
    }
    for (int i = 0; i < n; ++i) {
        quotes.emplace_back();
    }
    std::cout << "copies " << Tracker::copies << ", moves " << Tracker::moves << '\n';
}

int main() {
    std::cout << std::boolalpha << std::is_nothrow_move_constructible_v<Quote> << ' '
              << std::is_nothrow_move_constructible_v<LoggedQuote> << '\n';
    fill<Quote>("Quote, growing", 4, false);
    fill<LoggedQuote>("LoggedQuote, growing", 4, false);
    fill<LoggedQuote>("LoggedQuote, reserved", 4, true);
    return 0;
}

